\label{newlema61}
Let $f_1, \ldots, f_m,g,p_1,\ldots, p_n \in \mathcal{O}_n$, where $f_i$ and $g$ are relatively prime, for any $i \in \{ 1,\ldots,m \}$. Then
\begin{eqnarray*}
\dim_{\mathbb{C}} \frac{\mathcal{O}_n}{\langle f_1,\ldots,f_m,gp_1,\ldots,gp_n\rangle}&=&
\dim_{\mathbb{C}} \frac{\mathcal{O}_n}{\langle f_1,\ldots,f_m,p_1,\ldots,p_n\rangle}\\
& & +\dim_{\mathbb{C}} \frac{\mathcal{O}_n}{\langle f_1,\ldots,f_m,g\rangle}.
\end{eqnarray*}

Observe that \[\displaystyle\dim_{\mathbb{C}} \frac{\mathcal{O}_n}{\langle f_1,\ldots,f_m,r_1,\ldots,r_n\rangle}=\dim_{\mathbb{C}} \frac{\mathcal{O}}{\langle r_1',\ldots,r_n'\rangle},\] with $\mathcal{O}=\displaystyle\frac{\mathcal{O}_n}{\langle f_1,\ldots,f_m\rangle}$ and $r_i'=r_i+\langle f_1,\ldots,f_m\rangle$, for any $i \in \{ 1,\ldots,n \}$ and any $r_i \in \mathcal{O}_n$. The proof is completed using the following exact sequence:
\begin{align*}
0 \longrightarrow \frac{\mathcal{O}}{\langle p_1',\ldots,p_n'\rangle} \xrightarrow{ \ \sigma  \ } \ \frac{\mathcal{O}}{\langle g'p_1',\ldots,g'p_n'\rangle} \ \xrightarrow{ \ \delta  \ } \frac{\mathcal{O}}{\langle g'\rangle} \longrightarrow 0,
\end{align*}
where $\sigma(z'+\langle p_1',\ldots,p_n'\rangle)=g'z'+\langle g'p_1',\ldots,g'p_n'\rangle$ and $\delta(z'+\langle g'p_1',\ldots,g'p_n'\rangle)=z'+\langle g'\rangle$ for any $z' \in \mathcal{O}$.

We have $\mu_{BR}(\omega,X)=\operatorname{Ind}_{\operatorname{GSV} }(\omega;X,0)+\mu_0(\omega)-\tau_0(X)$ by Theorem \ref{mainresult}. On the other hand, $\operatorname{Ind}_{\operatorname{GSV} }(\omega;X,0)=\operatorname{Ind}_{\operatorname{rad} }(\omega;X,0)+\mu_0(X)$ by Proposition \ref{radial_gsv}. Therefore, 
\begin{equation}\label{eq_5}
\mu_{BR}(\omega,X)=\operatorname{Ind}_{\operatorname{rad} }(\omega;X,0)+\mu_0(X)+\mu_0(\omega)-\tau_0(X).
\end{equation}
The proof concludes by applying Proposition \ref{euler_radial} to $(X,0)$ and substituting into equation (\ref{eq_5}).

\label{ex4}
Let $X=\{\phi=0\}$, where $\phi:(\mathbb{C}^3,0) \rightarrow (\mathbb{C},0)$ is given by $\phi(x,y,z)=x^3+yz^2+y^3+xy^4$. Using \cite[Example 9]{Tajima2021}, we have 
\begin{align*}
    \Theta_X= \Big\langle &(3xy^2+3y^2+z^2)\frac{\partial}{\partial x}+(-3x^2-y^3)\frac{\partial}{\partial y}, \\
    &(2z^3)\frac{\partial}{\partial x}+(-6x^2z)\frac{\partial}{\partial y}+(9x^3y+9x^2y-y^2z^2)\frac{\partial}{\partial z}, \\
    &(2yz)\frac{\partial}{\partial x}+(-3x^2-y^3)\frac{\partial}{\partial z}, \\
    &(2yz)\frac{\partial}{\partial y}+(-3xy^2-3y^2-z^2)\frac{\partial}{\partial z}, \\
    & \left(-\frac{4}{3}x^2y-x \right)\frac{\partial}{\partial x}+\left(-\frac{2}{3} xy^2-y \right)\frac{\partial}{\partial y}+\left(-\frac{5}{3} xyz-z \right)\frac{\partial}{\partial z} \Big\rangle .
\end{align*}
Let $\omega=zdx+xdy+ydz$ a germ of a holomorphic $1$-form with isolated singularity at $0 \in \mathbb{C}^3$. Since
\begin{align*}
    \omega \wedge d\phi = &(z^3+3y^2z+4xy^3z-3x^3-xy^4) dx \wedge dy+ \\
    &(2yz^2-3x^2y-y^5) dx \wedge dz + (2xyz-yz^2-3y^3-4xy^4) dy \wedge dz.
\end{align*}
We deduce that $X$ is not invariant by $\omega$.
Using \textit{Singular} (\cite{DGPS}) to compute the indices, we verify that Theorem \ref{mainresult} holds, since $\mu_{BR}(\omega,X)=14$, $\operatorname{Ind}_{\operatorname{GSV} }(\omega;X,0)=21, \ \mu_0(\omega)=1$ and $\tau_0(X)=8$.

\label{lima_lema}
Let $\omega=\displaystyle\sum^n_{i=1}A_idx_i\in\Omega^1(\mathbb{C}^n,0)$ and let $g \in \mathcal{O}_n $ be such that $\dim V((\omega,dg)) = 1$ and $V(\omega) = \{0\}$ (here $(\omega):=\langle A_1,\ldots,A_n\rangle$ and $(\omega,dg)$  is the
ideal in $\mathcal{O}_n$ generated by the maximal minors of the matrix of $\left(A_i,\frac{\partial g}{\partial x_i}\right)$). Consider the following matrices
\[
A = \left(\begin{array}{ccc}
A_1 & \cdots & A_n\\
\frac{\partial g}{\partial x_1} & \cdots & \frac{\partial g}{\partial x_n}
\end{array}\right),
\quad
A' = \left(\begin{array}{cccc}
\mu & A_1 & \cdots & A_n \\
\lambda & \frac{\partial g}{\partial x_1} & \cdots &  \frac{\partial g}{\partial x_n}
\end{array}\right),
\]
where $\lambda, \mu \in \mathcal{O}_n$. Let $M, M'$ be the submodules of $\mathcal{O}^2_n$ generated by the columns of $A, A'$ respectively. If $I_2(A) = I_2(A')$ then $M = M'$.

\label{relthmBR} Let $\omega=\displaystyle\sum^n_{i=1}A_i(x)dx_i$ be a germ of a holomorphic 1-form with isolated singularity at $0\in\mathbb{C}^n$, $n\geq 2$, where $A_i\in\mathcal{O}_n$. Let $X=\{\phi=0\}$ be a germ of a complex analytic hypersurface with an isolated singularity at $0\in\mathbb{C}^n$.
 Assume that $X$ is not invariant by $\omega$. Then
 \begin{itemize}
     \item[(i)]$\dfrac{\Theta_X}{\Theta_X^T}\cong\dfrac{\omega(\Theta_X)+I_X}{\omega(\Theta_X^T)+I_X}$;
     \item[(ii)] $\omega(\Theta_X)\cap I_X=(\omega)\cdot I_X$;
     \item[(iii)] $\dfrac{\mathcal{O}_n}{(\omega)}\cong\dfrac{\omega(\Theta_X)+I_X}{\omega(\Theta_X)}$,
 \end{itemize}
where $(\omega):=\langle A_1,\ldots,A_n\rangle$ and $I_X=\langle\phi\rangle$.

\label{dim2}
Let $\mathcal{F}$ be a germ of a singular foliation at $(\mathbb{C}^2,0)$, and let $X$ be a germ of a reduced curve at $(\mathbb{C}^2,0)$. Assume that $X$ is not invariant by $\mathcal{F}$. 
Then 
\begin{equation} \label{princ}
\mu_{BR}(\mathcal{F},X)=\mu_0(\mathcal{F})+\operatorname{tang}(\mathcal{F},X,0)-\tau_0(X).
\end{equation}

\label{ex1}
Consider the curve $X$ given by $X=\{ \phi=y^p-x^q=0 \}$, and let $\mathcal{F}$ be a foliation defined by the $1$-form $\omega=\lambda xdy+ydx$, with $\lambda \neq -\displaystyle\frac{p}{q}$. Then, by \cite[Example 1]{Saito}, we have:
\begin{align*}
\Theta_X=\left\langle qy \frac{\partial}{\partial y}+px \frac{\partial}{\partial x}, py^{p-1} \frac{\partial}{\partial x}+qx^{q-1} \frac{\partial}{\partial y} \right\rangle.
\end{align*}
Note that $X$ is not invariant by $\mathcal{F}$, since
\begin{align*}
\omega \wedge d \phi = (\lambda xdy+ydx) \wedge (py^{p-1}dy -qx^{q-1}dx) = (py^p +\lambda q x^q) \ dx \wedge dy
\end{align*}
and $\lambda \neq -\displaystyle\frac{p}{q}$. Thus, we have $\mu_0(\mathcal{F})=1$, $\operatorname{tang}(\mathcal{F},X,0)=pq$, and $\tau_0(X)=(p-1)(q-1)$. Computing the Bruce-Roberts number in this case, we find
\begin{align*}
\mu_{BR}(\mathcal{F},X)=\dim_{\mathbb{C}} \frac{\mathcal{O}_2}{\omega(\Theta_X)}=p+q,
\end{align*}
which indeed satisfies equation (\ref{princ}).

\label{ex3}
Consider the foliation $\mathcal{F}_\omega$ (Suzuki's foliation) defined by the $1$-form
\begin{align*}
\omega=(y^3+y^2-xy)dx-(2xy^2+xy-x^2)dy,
\end{align*}
and the foliation $\mathcal{F}_\eta$ defined by the $1$-form
\begin{align*}
\eta=(2y^2+x^3)dx-2xydy.
\end{align*}
The foliations $\mathcal{F}_\omega$ and $\mathcal{F}_\eta$ are topologically conjugate (\cite[Chapter 2, Part 3]{CervMattei}). Using the curve $X$ from Example \ref{ex1}, with $p=7$ and $q=3$, i.e., $X=\{\phi=0\}$, with $\phi=y^7-x^3$, we have $\mu_{BR}(\mathcal{F}_\omega,X)=\mu_{BR}(\mathcal{F}_\eta,X)=17$, $\mu_0(\mathcal{F}_\omega)=\mu_0(\mathcal{F}_\eta)=5$, $\operatorname{tang}(\mathcal{F}_\omega,X,0)=\operatorname{tang}(\mathcal{F}_\eta,X,0)=24$, and $\tau_0(X)=12$. Thus, for both foliations, (\ref{princ}) is satisfied.

\label{tangirred}
Let $\mathcal{F}$ be a germ of a singular foliation at $(\mathbb{C}^2,0)$, and let $X$ be a germ of a reduced curve at $(\mathbb{C}^2,0)$ defined by $\phi: (\mathbb{C}^2, 0) \rightarrow (\mathbb{C},0)$. Suppose that $X$ is irreducible and not invariant by $\mathcal{F}$. Then
\begin{align*}
    \operatorname{tang}(\mathcal{F},X,0)=\text{ord}_{t=0} \ \varphi^* \omega+\mu_0(X),
\end{align*}
where $\varphi$ is a Puiseux parametrization of $X$.

\label{blowup}
Let $\mathcal{F}$ be a germ of a singular holomorphic foliation at $(\mathbb{C}^2,0)$, let $X$ be a germ of an irreducible reduced curve and let $\pi:\tilde{\mathbb{C}}^2 \rightarrow (\mathbb{C}^2,0)$ be the blow-up at $(\mathbb{C}^2,0)$. Assume that $X$ is not invariant by $\mathcal{F}$, $\tilde{\mathcal{F}}:=\pi^* \mathcal{F}$, and $q \in \pi^{-1}(0) \cap \tilde{X}$, where $\tilde{\mathcal{F}}$ and $\tilde{X}$ are the strict transforms of $\mathcal{F}$ and $X$ respectively. Denote by $m$ the multiplicity of $X$ in its Puiseux parametrization, and denote by $\nu$ the  algebraic multiplicity of the foliation $\mathcal{F}$ at $0\in\mathbb{C}^2$. Then, we have the following statements:
\begin{itemize}
\item[(a)] If $\pi$ is non-dicritical, then
\begin{align*}
\mu_{BR}(\mathcal{F},X,0)&=\mu_{BR}(\tilde{\mathcal{F}},\tilde{X},q)+\nu^2-\nu-1+\nu m \\
&+\displaystyle \sum_{\substack{p \in \pi^{-1}(0) \\ p \neq q}}  \mu_p(\tilde{\mathcal{F}}) +\frac{m(m-1)}{2}-\mathcal{D};
\end{align*}
\item[(b)] If $\pi$ is dicritical, then
\begin{align*}
\mu_{BR}(\mathcal{F},X,0)&=\mu_{BR}(\tilde{\mathcal{F}},\tilde{X},q)+\nu^2+\nu-1+(\nu+1)m \\
&+\displaystyle \sum_{\substack{p \in \pi^{-1}(0) \\ p \neq q}}  \mu_p(\tilde{\mathcal{F}}) +\frac{m(m-1)}{2}-\mathcal{D}.
\end{align*}
\end{itemize}
 We write $\mathcal{D}=\dim_{\mathbb{C}} \displaystyle\frac{\tilde{\sigma}^* \Omega_{\tilde{X}}}{\sigma^* \Omega_{X}}$, where $\tilde{\sigma}:(\overline{X},0) \rightarrow (\tilde{X},0)$ is the normalization, and $\sigma=\pi\circ\tilde{\sigma}$.

Let $\omega$ be the $1$-form defining $\mathcal{F}$ and let $\tilde{\omega}$ be the $1$-form defining $\tilde{\mathcal{F}}$. Applying Proposition \ref{tangirred} to the Corollary \ref{dim2}, we have

\begin{equation} \label{newbrob}
\mu_{BR}(\mathcal{F},X,0)=\mu_0(\mathcal{F})+\operatorname{ord}_{t=0} \varphi^* \omega +\mu_0(X)-\tau_0(X)
\end{equation}
and similarly,
\begin{align*}
\mu_{BR}(\tilde{\mathcal{F}},\tilde{X},q)=\mu_q(\tilde{\mathcal{F}})+\operatorname{ord}_{t=q} \tilde{\varphi}^* \tilde{\omega}+\mu_q(\tilde{X})-\tau_q(\tilde{X}),
\end{align*}
where $\varphi$ and $\tilde{\varphi}$ are the Puiseux parametrization of $X$ and $\tilde{X}$, respectively. 

The proof is obtained using results that show how the indexes on the right side of equation (\ref{newbrob}) change through a blow-up. From \cite[Proposition 4.13]{CanoCerv}, we have
\begin{align*} 
\mu_0(\mathcal{F})= \left\{ \begin{array}{cc}
\nu^2-(\nu+1)+\displaystyle\sum_{p \in \pi^{-1}(0)} \mu_p(\tilde{\mathcal{F}}) & \text{if} \ \pi \ \text{is non-dicritical;} \\
(\nu+1)^2-(\nu+2)+\displaystyle\sum_{p \in \pi^{-1}(0)} \mu_p(\tilde{\mathcal{F}}) & \text{if} \ \pi \ \text{is dicritical.}
\end{array} \right.
\end{align*}
and, from \cite[p. 4]{Wang}, we have
\begin{align*} 
\mu_0(X)-\mu_q(\tilde{X})=m(m-1) \ \text{and} \ \tau_0(X)-\tau_q(\tilde{X})=\displaystyle\frac{m(m-1)}{2}+\mathcal{D}.
\end{align*}
Now, from \cite[Section 2]{FPGBSM}, evaluating the $1$-form that defines $\tilde{\mathcal{F}}$ in $\tilde{\varphi}$ and taking orders, we get
\begin{align*}
\operatorname{ord}_{t=0} \varphi^* \omega= \left\{ \begin{array}{cc}
\nu m+ \operatorname{ord}_{t=q} \tilde{\varphi}^* \tilde{\omega} & \text{if} \ \pi \ \text{is non-dicritical;} \\
(\nu+1) m+\operatorname{ord}_{t=q} \tilde{\varphi}^* \tilde{\omega} & \text{if} \ \pi \ \text{is dicritical.}
\end{array} \right.
\end{align*}
Substituting the above formulas into (\ref{newbrob}), we conclude the proof of  the Proposition.

Let $\mathcal{F}$ be a foliation defined by the $1$-form $\omega=2xdy-3ydx$, and let $X$ be the curve given by $X=\{ \phi=y^2-x^5=0 \}$. Observe that $X$ is not invariant by $\mathcal{F}$. If $\pi$ is a blow-up at $0\in\mathbb{C}^2$, in local coordinates, we have
\begin{align*}
\tilde{\mathcal{F}}_1 &=\pi^* \mathcal{F}=x(-tdx+2xdt) \ \ \text{and} \\
\tilde{\mathcal{F}}_2 &=\pi^* \mathcal{F}=y(-3ydu-udy),
\end{align*}
where $\tilde{\mathcal{F}}_1$ is obtained using the local chart $\pi(x,t)=(x,tx)$, and $\tilde{\mathcal{F}}_2$ is obtained using the local chart $\pi(u,y)=(uy,y)$. Now, we consider $\tilde{X}=\{ t^2-x^3=0 \}$, since
\begin{align*}
\phi \circ  \pi(x,t)=\phi(x,tx)=x^2(t^2-x^3).
\end{align*}
Since $\tilde{X}$ is not invariant by $\tilde{\mathcal{F}}_1$, set $\tilde{\mathcal{F}}=\tilde{\mathcal{F}}_1$. Thus, $\tilde{\mathcal{F}}$ is defined by the $1$-form $\tilde{\omega}$, given by \[\tilde{\omega}=-tdx+2xdt.\] 
Using Singular (\cite{DGPS}), we get $\mu_{BR} (\mathcal{F},X,0)=7$, $\mu_{BR} (\tilde{\mathcal{F}},\tilde{X},q)=5$, $\nu=1$, $m=2$, $\displaystyle\sum_{\substack{p \in \pi^{-1}(0) \\ p \neq q}}  \mu_p(\tilde{\mathcal{F}})=\mu_0(\tilde{\mathcal{F}}_2)=1$ and $\mathcal{D}=1$. Note that
\begin{align*}
\mu_{BR}(\mathcal{F},X,0) &=\mu_{BR}(\tilde{\mathcal{F}},\tilde{X},q)+\nu^2-\nu-1+\nu m + \mu_0(\tilde{\mathcal{F}}_2) +\frac{m(m-1)}{2}-\mathcal{D} \\
&=5+1-1-1+2 \cdot 1+1+1-1=7.
\end{align*}
Since $\pi$ is non-dicritical, item $(a)$ of Proposition \ref{blowup} is satisfied.

Consider the foliation $\mathcal{F}$ defined by the $1$-form \[\omega=(2x^7+5y^5)dx-xy^2(5y^2+3x^5)dy,\] and let $X$ be the curve not invariant by $\mathcal{F}$ given by $X=\{ \phi=y^3-x^7=0 \}$. Again, by the local of the coordinates of the blow-up $\pi$ at $0\in\mathbb{C}^2$, we have
\begin{align*}
\tilde{\mathcal{F}}_1 &=\pi^* \mathcal{F}=x^5(-t^3dx-(2xt^2+t-1)dt) \ \ \text{and} \\
\tilde{\mathcal{F}}_2 &=\pi^* \mathcal{F}=y^5((y+1-u)du-udy),
\end{align*}
where $\tilde{\mathcal{F}}_1$ and $\tilde{\mathcal{F}}_2$ are obtained using the local charts $\pi(x,t)=(x,tx)$ and $\pi(u,y)=(uy,y)$, respectively. Set $\tilde{X}=\{ t^3-x^4=0 \}$, since
\begin{align*}
\phi \circ  \pi(x,t)=\phi(x,tx)=x^3(t^3-x^4).
\end{align*}
Since $\tilde{X}$ is not invariant by $\tilde{\mathcal{F}}_1$, set $\tilde{\mathcal{F}}=\tilde{\mathcal{F}}_1$. In that way, $\tilde{\mathcal{F}}$ is defined by the $1$-form \[\tilde{\omega}=-t^3dx-(2xt^2+t-1)dt.\] Again, by Singular \cite{DGPS}, we obtain $\mu_{BR} (\mathcal{F},X,0)=56$, $\mu_{BR} (\tilde{\mathcal{F}},\tilde{X},q)=9$, $\nu=5$, $m=3$, $\displaystyle\sum_{\substack{p \in \pi^{-1}(0) \\ p \neq q}}  \mu_p(\tilde{\mathcal{F}})=\mu_0(\tilde{\mathcal{F}}_2)=0$ and $\mathcal{D}=3$. Then,
\begin{eqnarray*}
\mu_{BR}(\mathcal{F},X,0) &=& \mu_{BR}(\tilde{\mathcal{F}},\tilde{X},q)+\nu^2+\nu-1+(\nu+1) m + \mu_0(\tilde{\mathcal{F}}_2) +\frac{m(m-1)}{2}-\mathcal{D} \\
&=&9+25+5-1+6 \cdot 3+0+3-3=56.
\end{eqnarray*}
Since $\pi$ is dicritical, item $(b)$ of Proposition \ref{blowup} is satisfied.

We can use Singular \cite{DGPS} to compute the relative Bruce-Roberts number for the previous examples:
    \begin{itemize}
        \item In Example \ref{ex1}, we have $\mathcal{F}:\omega=\lambda xdy+ydx=0, \ \lambda \neq -p/q$, and $X=\{ \phi=y^p-x^q=0 \}$. As we needed numerical examples, for $\lambda=1$, we have
        \begin{align*}
            &\mu_{BR}^-(\mathcal{F},X)=6, \ \text{when} \ p=2 \ \text{and} \ q=5, \ \text{and} \\ &\mu_{BR}^-(\mathcal{F},X)=23, \ \text{when} \ p=11 \ \text{and} \ q=13.
        \end{align*}
        In both cases, $\mu_{BR}^-(\mathcal{F},X)=p+q-1=\mu_{BR}(\mathcal{F},X)-\mu_0(\mathcal{F})$. \\
         \item In Example \ref{ex3}, we have $\mathcal{F}_{\omega}:\omega=(y^3+y^2-xy)dx-(2xy^2+xy-x^2)dy=0$, $\mathcal{F}_{\eta}:\eta=(2y^2+x^3)dx-2xydy=0$ and $X=\{ \phi=y^7-x^3=0 \}$, with $\mu_{BR}(\mathcal{F}_{\omega},X)=\mu_{BR}(\mathcal{F}_{\eta},X)=17$ and $\mu_0(\mathcal{F}_{\omega})=\mu_0(\mathcal{F}_{\eta})=5$. Then
        \begin{align*}
            \mu_{BR}^-(\mathcal{F}_{\omega},X)=\mu_{BR}^-(\mathcal{F}_{\eta},X)=12.
        \end{align*}

    \end{itemize}
    In each case, we have $\mu_{BR}^-(\mathcal{F},X)=\mu_{BR}(\mathcal{F},X)-\mu_0(\mathcal{F})$, satisfying Corollary \ref{red2}.

\label{bruce}
Let $\mathcal{F}$ be a germ of a singular holomorphic foliation at $(\mathbb{C}^2,0)$, let $X$ be a germ of an irreducible reduced curve and let $\pi:\tilde{\mathbb{C}}^2 \rightarrow (\mathbb{C}^2,0)$ be the blow-up at $(\mathbb{C}^2,0)$. Assume that $X$ is not invariant by $\mathcal{F}$, $\tilde{\mathcal{F}}:=\pi^* \mathcal{F}$, and $q \in \pi^{-1}(0) \cap \tilde{X}$, where $\tilde{\mathcal{F}}$ and $\tilde{X}$ are the strict transforms of $\mathcal{F}$ and $X$ respectively. Denote by $m$ the multiplicity of $X$ in its Puiseux parametrization, and denote by $\nu$ the  algebraic multiplicity of the foliation $\mathcal{F}$ at $0\in\mathbb{C}^2$. Then, we have the following statements:
\begin{itemize}
\item[(a)] If $\pi$ is non-dicritical, then
\begin{align*}
\mu_{BR}^-(\mathcal{F},X,0)&=\mu_{BR}^-(\tilde{\mathcal{F}},\tilde{X},q)+\nu m +\frac{m(m-1)}{2}-\mathcal{D};
\end{align*}
\item[(b)] If $\pi$ is dicritical, then
\begin{align*}
\mu_{BR}^-(\mathcal{F},X,0)&=\mu_{BR}^-(\tilde{\mathcal{F}},\tilde{X},q)+(\nu+1)m +\frac{m(m-1)}{2}-\mathcal{D}.
\end{align*}
\end{itemize}
We write $\mu_{BR}^-(\mathcal{F},X,p)$ to denote the relative Bruce-Roberts number around the point $p$. Moreover, we have $\mathcal{D}=\dim \displaystyle\frac{\tilde{\sigma}^* \Omega_{\tilde{X}}}{\sigma^* \Omega_{X}}$, where $\tilde{\sigma}:(\overline{X},0) \rightarrow (\tilde{X},0)$ is the normalization, and $\sigma=\pi\circ\tilde{\sigma}$.

\label{inv}
Let $\mathcal{F}$ be a holomorphic foliation on a compact complex surface $S$, and let $X\subset S$ be a compact curve, none of whose components are invariant by $\mathcal{F}$. Then
\[\tau(X)\leq T_\mathcal{F} \cdot T_{\mathcal{F}}+T_{\mathcal{F}}\cdot K_S+c_2(S)+N_{\mathcal{F}}\cdot X-\chi(X).\]
